1	/**
2	 * name.com API v4 client (reseller). Auth: HTTP Basic (username:token).
3	 * Production: https://api.name.com  ·  Dev/sandbox: https://api.dev.name.com
4	 */
5	
6	export function registrarConfigured(): boolean {
7	  return !!(process.env.NAMECOM_USERNAME && process.env.NAMECOM_TOKEN);
8	}
9	
10	function baseUrl(): string {
11	  return process.env.NAMECOM_ENV === "dev" ? "https://api.dev.name.com" : "https://api.name.com";
12	}
13	
14	function authHeader(): string {
15	  const raw = `${process.env.NAMECOM_USERNAME}:${process.env.NAMECOM_TOKEN}`;
16	  return "Basic " + Buffer.from(raw).toString("base64");
17	}
18	
19	async function nc(method: string, path: string, body?: unknown): Promise<any> {
20	  if (!registrarConfigured()) throw new Error("Domain registrar (name.com) is not configured");
21	  const res = await fetch(`${baseUrl()}${path}`, {
22	    method,
23	    headers: { Authorization: authHeader(), "Content-Type": "application/json" },
24	    body: body ? JSON.stringify(body) : undefined,
25	    signal: AbortSignal.timeout(30_000),
26	  });
27	  const text = await res.text();
28	  let json: any = {};
29	  try {
30	    json = text ? JSON.parse(text) : {};
31	  } catch {
32	    /* non-JSON error body */
33	  }
34	  if (!res.ok) {
35	    const msg = json?.message || json?.details || text || `HTTP ${res.status}`;
36	    throw new Error(`name.com: ${msg}`);
37	  }
38	  return json;
39	}
40	
41	const dollarsToCents = (d: number | undefined) => (d === undefined ? null : Math.round(d * 100));
42	
43	/** Platform markup added to the registrar cost, as a percentage (admin-tunable via env). */
44	export function domainMarkupPct(): number {
45	  return Number(process.env.DOMAIN_MARKUP_PCT ?? 25);
46	}
47	
48	/** Retail (customer) price for a given registrar cost, markup applied. */
49	export function retailCents(costCents: number | null): number | null {
50	  if (costCents === null) return null;
51	  return Math.round(costCents * (1 + domainMarkupPct() / 100));
52	}
53	
54	export type DomainCheck = {
55	  domain: string;
56	  available: boolean;
57	  premium: boolean;
58	  priceCents: number | null; // RETAIL — what the customer pays (per year)
59	  costCents: number | null; // registrar cost (per year)
60	  renewCents: number | null; // RETAIL renewal price
61	};
62	
63	export async function checkDomains(domains: string[]): Promise<DomainCheck[]> {
64	  const json = await nc("POST", "/v4/domains:checkAvailability", { domainNames: domains });
65	  return (json.results ?? []).map((r: any) => {
66	    const cost = dollarsToCents(r.purchasePrice);
67	    const renewCost = dollarsToCents(r.renewalPrice ?? r.purchasePrice);
68	    return {
69	      domain: r.domainName,
70	      available: r.purchasable === true,
71	      premium: r.premium === true,
72	      priceCents: retailCents(cost),
73	      costCents: cost,
74	      renewCents: retailCents(renewCost),
75	    };
76	  });
77	}
78	
79	export type RegistrantContact = {
80	  firstName: string;
81	  lastName: string;
82	  address1: string;
83	  city: string;
84	  stateProvince: string;
85	  postalCode: string;
86	  country: string; // ISO-2
87	  phone: string; // +NN.NNNNNNNNNN
88	  email: string;
89	};
90	
91	function ncContact(c: RegistrantContact) {
92	  return {
93	    firstName: c.firstName,
94	    lastName: c.lastName,
95	    address1: c.address1,
96	    city: c.city,
97	    state: c.stateProvince,
98	    zip: c.postalCode,
99	    country: c.country,
100	    phone: c.phone,
101	    email: c.email,
102	  };
103	}
104	
105	/** Registers for `years` at the given expected price (from checkDomains). */
106	export async function registerDomain(
107	  domain: string,
108	  years: number,
109	  contact: RegistrantContact,
110	  purchaseCents: number
111	): Promise<{ expiresAt?: Date }> {
112	  const c = ncContact(contact);
113	  const json = await nc("POST", "/v4/domains", {
114	    domain: {
115	      domainName: domain,
116	      contacts: { registrant: c, admin: c, tech: c, billing: c },
117	      privacyEnabled: true,
118	    },
119	    purchasePrice: purchaseCents / 100,
120	    years,
121	  });
122	  const exp = json?.domain?.expireDate ?? json?.order?.expireDate;
123	  return { expiresAt: exp ? new Date(exp) : undefined };
124	}
125	
126	export async function renewDomain(domain: string, years: number, purchaseCents: number): Promise<void> {
127	  await nc("POST", `/v4/domains/${encodeURIComponent(domain)}:renew`, {
128	    purchasePrice: purchaseCents / 100,
129	    years,
130	  });
131	}
132	
133	export async function domainInfo(domain: string): Promise<{ expires?: Date; created?: Date }> {
134	  const json = await nc("GET", `/v4/domains/${encodeURIComponent(domain)}`);
135	  return {
136	    expires: json?.expireDate ? new Date(json.expireDate) : undefined,
137	    created: json?.createDate ? new Date(json.createDate) : undefined,
138	  };
139	}
140	
141	// ---------- DNS ----------
142	
143	export type DnsRecord = {
144	  id: number;
145	  host: string; // "" = apex
146	  type: string;
147	  answer: string;
148	  ttl: number;
149	  priority?: number;
150	};
151	
152	export async function listRecords(domain: string): Promise<DnsRecord[]> {
153	  const json = await nc("GET", `/v4/domains/${encodeURIComponent(domain)}/records`);
154	  return (json.records ?? []).map((r: any) => ({
155	    id: r.id,
156	    host: r.host ?? "",
157	    type: r.type,
158	    answer: r.answer,
159	    ttl: r.ttl ?? 300,
160	    priority: r.priority,
161	  }));
162	}
163	
164	export async function addRecord(
165	  domain: string,
166	  rec: { host: string; type: string; answer: string; ttl?: number; priority?: number }
167	): Promise<void> {
168	  await nc("POST", `/v4/domains/${encodeURIComponent(domain)}/records`, {
169	    host: rec.host,
170	    type: rec.type,
171	    answer: rec.answer,
172	    ttl: rec.ttl ?? 300,
173	    ...(rec.priority !== undefined ? { priority: rec.priority } : {}),
174	  });
175	}
176	
177	export async function deleteRecord(domain: string, id: number): Promise<void> {
178	  await nc("DELETE", `/v4/domains/${encodeURIComponent(domain)}/records/${id}`);
179	}
180	
181	/** Read-only view used by the DNS UI: apex host shown as "@". */
182	export type DnsHost = { name: string; type: string; address: string; ttl: number; mxPref?: number };
183	
184	export async function getDnsHosts(domain: string): Promise<DnsHost[]> {
185	  const recs = await listRecords(domain);
186	  return recs.map((r) => ({
187	    name: r.host === "" ? "@" : r.host,
188	    type: r.type,
189	    address: r.answer,
190	    ttl: r.ttl,
191	    mxPref: r.priority,
192	  }));
193	}
