1	"use server";
2	
3	import { revalidatePath } from "next/cache";
4	import { redirect } from "next/navigation";
5	import { z } from "zod";
6	import { db } from "./db";
7	import { requireUser } from "./auth";
8	import {
9	  registrarConfigured,
10	  checkDomains,
11	  registerDomain,
12	  renewDomain,
13	  domainInfo,
14	  listRecords,
15	  addRecord,
16	  deleteRecord,
17	  type RegistrantContact,
18	} from "./registrar";
19	import { domainTerm, domainTermPriceCents } from "./billing-terms";
20	import { debitWallet, InsufficientBalanceError } from "./wallet";
21	
22	const DOMAIN_RE = /^[a-z0-9]([a-z0-9-]{0,61}[a-z0-9])?\.[a-z]{2,24}$/;
23	
24	export async function purchaseDomain(prev: any, formData: FormData): Promise<{ error?: string }> {
25	  const user = await requireUser();
26	  if (!registrarConfigured()) {
27	    return { error: "Domain registration is not configured yet (name.com API keys missing)." };
28	  }
29	  const contactSchema = z.object({
30	    firstName: z.string().min(1).max(60),
31	    lastName: z.string().min(1).max(60),
32	    address1: z.string().min(1).max(120),
33	    city: z.string().min(1).max(60),
34	    stateProvince: z.string().min(1).max(60),
35	    postalCode: z.string().min(1).max(20),
36	    country: z.string().length(2),
37	    phone: z.string().regex(/^\+\d{1,3}\.\d{4,14}$/, "Phone format: +1.5551234567"),
38	    email: z.string().email(),
39	  });
40	  const domain = String(formData.get("domain") ?? "").toLowerCase().trim();
41	  if (!DOMAIN_RE.test(domain)) return { error: "Invalid domain name." };
42	  const dTerm = domainTerm(Number(formData.get("years") ?? 1));
43	
44	  const contactParsed = contactSchema.safeParse({
45	    firstName: formData.get("firstName"),
46	    lastName: formData.get("lastName"),
47	    address1: formData.get("address1"),
48	    city: formData.get("city"),
49	    stateProvince: formData.get("stateProvince"),
50	    postalCode: formData.get("postalCode"),
51	    country: String(formData.get("country") ?? "").toUpperCase(),
52	    phone: formData.get("phone"),
53	    email: formData.get("email"),
54	  });
55	  if (!contactParsed.success) {
56	    return { error: contactParsed.error.issues[0]?.message ?? "Invalid registrant contact." };
57	  }
58	
59	  if (await db.domain.findUnique({ where: { name: domain } })) {
60	    return { error: "This domain is already managed by another account." };
61	  }
62	
63	  // Live availability + retail(markup) & cost prices from name.com
64	  let priceCents: number; // retail per year (customer)
65	  let costCents: number; // registrar cost per year (us)
66	  try {
67	    const [check] = await checkDomains([domain]);
68	    if (!check) return { error: "Could not check availability. Try again." };
69	    if (!check.available) return { error: "Domain is not available." };
70	    if (check.premium) return { error: "Premium domains are not supported yet." };
71	    if (check.priceCents === null || check.costCents === null) return { error: "No price available for this TLD." };
72	    priceCents = check.priceCents;
73	    costCents = check.costCents;
74	  } catch (e: any) {
75	    return { error: String(e?.message ?? e).slice(0, 200) };
76	  }
77	
78	  const totalCents = domainTermPriceCents(priceCents, dTerm.years); // customer pays (retail, term-discounted)
79	  const registrarCostCents = costCents * dTerm.years; // we pay name.com the true cost
80	  if (user.balanceCents < totalCents) {
81	    return { error: `Insufficient balance — ${dTerm.label} costs $${(totalCents / 100).toFixed(2)}.` };
82	  }
83	
84	  let record;
85	  try {
86	    record = await db.$transaction(async (tx) => {
87	      await debitWallet(tx, user.id, totalCents);
88	      await tx.walletTransaction.create({
89	        data: { userId: user.id, amountCents: -totalCents, description: `Domain registration: ${domain} (${dTerm.label})` },
90	      });
91	      return tx.domain.create({
92	        data: { name: domain, userId: user.id, priceCents, costCents, termYears: dTerm.years, status: "PENDING", registrar: "name.com" },
93	      });
94	    });
95	  } catch (e) {
96	    if (e instanceof InsufficientBalanceError) return { error: "Insufficient balance — top up your wallet first." };
97	    throw e;
98	  }
99	
100	  try {
101	    const { expiresAt } = await registerDomain(domain, dTerm.years, contactParsed.data as RegistrantContact, registrarCostCents);
102	    const info = expiresAt ? { expires: expiresAt } : await domainInfo(domain).catch(() => ({ expires: undefined }));
103	    await db.domain.update({
104	      where: { id: record.id },
105	      data: {
106	        status: "ACTIVE",
107	        registeredAt: new Date(),
108	        expiresAt: info.expires ?? new Date(Date.now() + dTerm.years * 365 * 86400_000),
109	      },
110	    });
111	    await db.auditLog.create({ data: { userId: user.id, action: "domain.register", detail: `${domain} ${dTerm.years}yr` } });
112	    await db.notification.create({
113	      data: { userId: user.id, title: `Domain registered: ${domain}`, href: `/dashboard/domains/${record.id}` },
114	    });
115	  } catch (e: any) {
116	    await db.$transaction([
117	      db.user.update({ where: { id: user.id }, data: { balanceCents: { increment: totalCents } } }),
118	      db.walletTransaction.create({
119	        data: { userId: user.id, amountCents: totalCents, description: `Refund: failed registration ${domain}` },
120	      }),
121	      db.domain.update({
122	        where: { id: record.id },
123	        data: { status: "FAILED", error: String(e?.message ?? e).slice(0, 500) },
124	      }),
125	    ]);
126	    return { error: `Registration failed: ${String(e?.message ?? e).slice(0, 200)} (you were refunded).` };
127	  }
128	  redirect(`/dashboard/domains/${record.id}`);
129	}
130	
131	export async function renewDomainAction(domainId: string): Promise<{ error?: string }> {
132	  const user = await requireUser();
133	  const domain = await db.domain.findUnique({ where: { id: domainId } });
134	  if (!domain || (domain.userId !== user.id && user.role !== "ADMIN")) return { error: "Not found." };
135	  const dTerm = domainTerm(domain.termYears);
136	  const renewCents = domainTermPriceCents(domain.priceCents, dTerm.years);
137	  const owner = await db.user.findUnique({ where: { id: domain.userId } });
138	  if (!owner || owner.balanceCents < renewCents) return { error: "Insufficient balance." };
139	
140	  try {
141	    await renewDomain(domain.name, dTerm.years, (domain.costCents || domain.priceCents) * dTerm.years);
142	  } catch (e: any) {
143	    return { error: `Renewal failed: ${String(e?.message ?? e).slice(0, 200)}` };
144	  }
145	  try {
146	    await db.$transaction(async (tx) => {
147	      await debitWallet(tx, domain.userId, renewCents);
148	      await tx.walletTransaction.create({
149	        data: { userId: domain.userId, amountCents: -renewCents, description: `Domain renewal: ${domain.name} (${dTerm.label})` },
150	      });
151	      await tx.domain.update({
152	        where: { id: domainId },
153	        data: {
154	          expiresAt: new Date((domain.expiresAt ?? new Date()).getTime() + dTerm.years * 365 * 86400_000),
155	          status: "ACTIVE",
156	        },
157	      });
158	    });
159	  } catch (e) {
160	    if (e instanceof InsufficientBalanceError) return { error: "Insufficient balance." };
161	    throw e;
162	  }
163	  revalidatePath(`/dashboard/domains/${domainId}`);
164	  return {};
165	}
166	
167	export async function toggleDomainAutoRenew(domainId: string) {
168	  const user = await requireUser();
169	  const domain = await db.domain.findUnique({ where: { id: domainId } });
170	  if (!domain || (domain.userId !== user.id && user.role !== "ADMIN")) throw new Error("Forbidden");
171	  await db.domain.update({ where: { id: domainId }, data: { autoRenew: !domain.autoRenew } });
172	  revalidatePath(`/dashboard/domains/${domainId}`);
173	}
174	
175	// ---------- DNS management ----------
176	
177	const RECORD_TYPES = ["A", "AAAA", "CNAME", "TXT", "MX", "NS", "SRV", "ALIAS"] as const;
178	
179	async function ownedDomain(domainId: string) {
180	  const user = await requireUser();
181	  const domain = await db.domain.findUnique({ where: { id: domainId } });
182	  if (!domain || (domain.userId !== user.id && user.role !== "ADMIN")) throw new Error("Forbidden");
183	  if (domain.status !== "ACTIVE") throw new Error("Domain is not active");
184	  return { user, domain };
185	}
186	
187	export async function addDnsRecord(prev: any, formData: FormData): Promise<{ error?: string }> {
188	  const domainId = String(formData.get("domainId") ?? "");
189	  let ctx;
190	  try {
191	    ctx = await ownedDomain(domainId);
192	  } catch (e: any) {
193	    return { error: e.message };
194	  }
195	  const parsed = z
196	    .object({
197	      name: z.string().max(120).default(""),
198	      type: z.enum(RECORD_TYPES),
199	      address: z.string().min(1).max(500),
200	      ttl: z.coerce.number().int().min(60).max(86400).default(300),
201	      mxPref: z.coerce.number().int().min(0).max(65535).optional(),
202	    })
203	    .safeParse({
204	      name: formData.get("name") ?? "",
205	      type: formData.get("type"),
206	      address: formData.get("address"),
207	      ttl: formData.get("ttl") || 300,
208	      mxPref: formData.get("mxPref") || undefined,
209	    });
210	  if (!parsed.success) return { error: parsed.error.issues[0]?.message ?? "Invalid record." };
211	
212	  // "@" or blank => apex (name.com uses empty host for apex)
213	  const host = ["@", ""].includes(parsed.data.name.trim()) ? "" : parsed.data.name.trim();
214	  try {
215	    await addRecord(ctx.domain.name, {
216	      host,
217	      type: parsed.data.type,
218	      answer: parsed.data.address,
219	      ttl: parsed.data.ttl,
220	      priority: parsed.data.type === "MX" || parsed.data.type === "SRV" ? parsed.data.mxPref ?? 10 : undefined,
221	    });
222	  } catch (e: any) {
223	    return { error: String(e?.message ?? e).slice(0, 200) };
224	  }
225	  revalidatePath(`/dashboard/domains/${domainId}`);
226	  return {};
227	}
228	
229	export async function deleteDnsRecord(
230	  domainId: string,
231	  record: { name: string; type: string; address: string }
232	): Promise<{ error?: string }> {
233	  let ctx;
234	  try {
235	    ctx = await ownedDomain(domainId);
236	  } catch (e: any) {
237	    return { error: e.message };
238	  }
239	  const wantHost = ["@", ""].includes(record.name) ? "" : record.name;
240	  try {
241	    const recs = await listRecords(ctx.domain.name);
242	    const match = recs.find((r) => r.host === wantHost && r.type === record.type && r.answer === record.address);
243	    if (!match) return { error: "Record not found (it may have already been removed)." };
244	    await deleteRecord(ctx.domain.name, match.id);
245	  } catch (e: any) {
246	    return { error: String(e?.message ?? e).slice(0, 200) };
247	  }
248	  revalidatePath(`/dashboard/domains/${domainId}`);
249	  return {};
250	}
251	
252	/** One-click: point apex + www at the platform's public IP. */
253	export async function pointDomainAtServer(domainId: string): Promise<{ error?: string }> {
254	  let ctx;
255	  try {
256	    ctx = await ownedDomain(domainId);
257	  } catch (e: any) {
258	    return { error: e.message };
259	  }
260	  const ip = process.env.PUBLIC_IP;
261	  if (!ip) return { error: "Public IP not configured." };
262	  try {
263	    const recs = await listRecords(ctx.domain.name);
264	    for (const r of recs) {
265	      if (["", "www"].includes(r.host) && r.type === "A") await deleteRecord(ctx.domain.name, r.id);
266	    }
267	    await addRecord(ctx.domain.name, { host: "", type: "A", answer: ip, ttl: 300 });
268	    await addRecord(ctx.domain.name, { host: "www", type: "A", answer: ip, ttl: 300 });
269	  } catch (e: any) {
270	    return { error: String(e?.message ?? e).slice(0, 200) };
271	  }
272	  revalidatePath(`/dashboard/domains/${domainId}`);
273	  return {};
274	}
