4	import { db } from "./db";
5	import { requireUser } from "./auth";
6	import { registrarConfigured } from "./registrar";
7	
8	/* ------------------------------------------------------------------ *
9	 * Minimal name.com v4 client (Basic auth), mirroring lib/registrar.ts.
10	 * These endpoints aren't exposed by the shared registrar helper, so we
11	 * call them directly here. All calls are guarded by registrarConfigured().
12	 * ------------------------------------------------------------------ */
13	
