20	  return "Basic " + Buffer.from(raw).toString("base64");
21	}
22	
23	async function nc(method: string, path: string, body?: unknown): Promise<any> {
24	  if (!registrarConfigured()) throw new Error("Domain registrar (name.com) is not configured");
25	  const res = await fetch(`${baseUrl()}${path}`, {
26	    method,
27	    headers: { Authorization: authHeader(), "Content-Type": "application/json" },
28	    body: body !== undefined ? JSON.stringify(body) : undefined,
29	    signal: AbortSignal.timeout(30_000),
30	  });
31	  const text = await res.text();
32	  let json: any = {};
33	  try {
34	    json = text ? JSON.parse(text) : {};
35	  } catch {
36	    /* non-JSON error body */
37	  }
38	  if (!res.ok) {
39	    const msg = json?.message || json?.details || text || `HTTP ${res.status}`;
