"use server";

import { revalidatePath } from "next/cache";
import { z } from "zod";
import { db } from "./db";
import { requireUser } from "./auth";
import {
  registrarConfigured,
  listRecords,
  addRecord,
  deleteRecord,
  type DnsRecord,
} from "./registrar";

/* ------------------------------------------------------------------ *
 * DNS super-manager actions for the customer domain manager.
 *
 * Reuses lib/registrar.ts's DNS helpers (listRecords/addRecord/
 * deleteRecord) for all record mutations. name.com endpoints not exposed
 * by that helper (URL forwarding, registrar lock) are called directly via
 * a minimal Basic-auth client that mirrors lib/registrar.ts, exactly like
 * lib/actions-domains-advanced.ts does. Everything is ownership-checked and
 * degrades gracefully (persist intent + a clear note) when the registrar
 * isn't configured or a TLD/endpoint isn't supported.
 * ------------------------------------------------------------------ */

function baseUrl(): string {
  return process.env.NAMECOM_ENV === "dev" ? "https://api.dev.name.com" : "https://api.name.com";
}

function authHeader(): string {
  const raw = `${process.env.NAMECOM_USERNAME}:${process.env.NAMECOM_TOKEN}`;
  return "Basic " + Buffer.from(raw).toString("base64");
}

async function nc(method: string, path: string, body?: unknown): Promise<any> {
  if (!registrarConfigured()) throw new Error("Domain registrar (name.com) is not configured");
  const res = await fetch(`${baseUrl()}${path}`, {
    method,
    headers: { Authorization: authHeader(), "Content-Type": "application/json" },
    body: body !== undefined ? JSON.stringify(body) : undefined,
    signal: AbortSignal.timeout(30_000),
  });
  const text = await res.text();
  let json: any = {};
  try {
    json = text ? JSON.parse(text) : {};
  } catch {
    /* non-JSON error body */
  }
  if (!res.ok) {
    const msg = json?.message || json?.details || text || `HTTP ${res.status}`;
    throw new Error(`name.com: ${msg}`);
  }
  return json;
}

function errMsg(e: unknown): string {
  return String(e instanceof Error ? e.message : e).slice(0, 200);
}

async function ownedDomain(domainId: string) {
  const user = await requireUser();
  const domain = await db.domain.findUnique({ where: { id: domainId } });
  if (!domain) throw new Error("Not found");
  if (domain.userId !== user.id && user.role !== "ADMIN") throw new Error("Forbidden");
  return { user, domain };
}

async function ownedActiveDomain(domainId: string) {
  const ctx = await ownedDomain(domainId);
  if (ctx.domain.status !== "ACTIVE") throw new Error("Domain is not active");
  if (!registrarConfigured()) throw new Error("Domain registrar (name.com) is not configured");
  return ctx;
}

/* A record shape the client can build for presets / imports. Host "" = apex. */
export type RecordInput = {
  host: string;
  type: string;
  answer: string;
  ttl?: number;
  priority?: number;
};

const RECORD_TYPES = ["A", "AAAA", "CNAME", "TXT", "MX", "NS", "SRV", "ALIAS"] as const;

function normHost(h: string): string {
  const t = (h ?? "").trim();
  return ["@", ""].includes(t) ? "" : t.replace(/\.$/, "");
}

/** True if `want` is already present in `existing` (host+type+answer, MX also priority). */
function recordExists(existing: DnsRecord[], want: RecordInput): boolean {
  const wh = normHost(want.host);
  const wa = want.answer.trim().toLowerCase();
  return existing.some((r) => {
    if (r.host !== wh) return false;
    if (r.type !== want.type) return false;
    if (r.answer.trim().toLowerCase() !== wa) return false;
    if (want.type === "MX" && want.priority !== undefined) return (r.priority ?? 10) === want.priority;
    return true;
  });
}

const recordInputSchema = z.object({
  host: z.string().max(120).default(""),
  type: z.enum(RECORD_TYPES),
  answer: z.string().min(1).max(2000),
  ttl: z.coerce.number().int().min(60).max(86400).default(300),
  priority: z.coerce.number().int().min(0).max(65535).optional(),
});

export type BulkResult = {
  error?: string;
  added?: string[];
  skipped?: string[];
  failed?: { record: string; reason: string }[];
  note?: string;
};

function label(r: RecordInput): string {
  const h = normHost(r.host) || "@";
  const pri = r.type === "MX" && r.priority !== undefined ? `${r.priority} ` : "";
  return `${r.type} ${h} → ${pri}${r.answer}`;
}

/**
 * Add many DNS records at once, skipping any that already exist. Powers the
 * quick-setup presets and DNS import. Ownership-checked; domain must be ACTIVE.
 */
export async function addDnsRecordsBulk(
  domainId: string,
  records: RecordInput[]
): Promise<BulkResult> {
  let ctx;
  try {
    ctx = await ownedActiveDomain(domainId);
  } catch (e) {
    return { error: errMsg(e) };
  }
  if (!Array.isArray(records) || records.length === 0) return { error: "No records to add." };
  if (records.length > 100) return { error: "Too many records in one request (max 100)." };

  const clean: RecordInput[] = [];
  for (const raw of records) {
    const parsed = recordInputSchema.safeParse(raw);
    if (!parsed.success) {
      return { error: `Invalid record: ${parsed.error.issues[0]?.message ?? "bad record"}` };
    }
    clean.push({ ...parsed.data, host: normHost(parsed.data.host) });
  }

  let existing: DnsRecord[];
  try {
    existing = await listRecords(ctx.domain.name);
  } catch (e) {
    return { error: `Could not read current records: ${errMsg(e)}` };
  }

  const added: string[] = [];
  const skipped: string[] = [];
  const failed: { record: string; reason: string }[] = [];

  for (const rec of clean) {
    if (recordExists(existing, rec)) {
      skipped.push(label(rec));
      continue;
    }
    try {
      await addRecord(ctx.domain.name, {
        host: rec.host,
        type: rec.type,
        answer: rec.answer,
        ttl: rec.ttl ?? 300,
        priority: rec.type === "MX" || rec.type === "SRV" ? rec.priority ?? 10 : undefined,
      });
      added.push(label(rec));
      // Track locally so later records in the same batch dedupe correctly.
      existing.push({ id: -1, host: rec.host, type: rec.type, answer: rec.answer, ttl: rec.ttl ?? 300, priority: rec.priority });
    } catch (e) {
      failed.push({ record: label(rec), reason: errMsg(e) });
    }
  }

  await db.auditLog.create({
    data: {
      userId: ctx.user.id,
      action: "domain.dns_bulk_add",
      detail: `${ctx.domain.name}: +${added.length} skip ${skipped.length} fail ${failed.length}`,
    },
  });
  revalidatePath(`/dashboard/domains/${domainId}`);
  return { added, skipped, failed: failed.length ? failed : undefined };
}

/* ------------------------------------------------------------------ *
 * DNS import (paste) — CSV / zone-ish text: name,type,value[,ttl[,priority]]
 * Lines starting with # or ; are ignored. Whitespace or comma separated.
 * ------------------------------------------------------------------ */

export type ParsedImport = { records: RecordInput[]; errors: string[] };

/** Pure parser exported so the UI can preview before applying. */
export async function parseDnsImport(text: string): Promise<ParsedImport> {
  const records: RecordInput[] = [];
  const errors: string[] = [];
  const lines = (text ?? "").split(/\r?\n/);
  lines.forEach((line, i) => {
    const raw = line.trim();
    if (!raw || raw.startsWith("#") || raw.startsWith(";")) return;
    // split on comma OR whitespace, but keep the value token intact if quoted
    let parts: string[];
    if (raw.includes(",")) parts = raw.split(",").map((p) => p.trim());
    else parts = raw.split(/\s+/);
    if (parts.length < 3) {
      errors.push(`Line ${i + 1}: expected at least name, type, value`);
      return;
    }
    const [nameTok, typeTok, valueTok, ttlTok, prioTok] = parts;
    const type = typeTok.toUpperCase();
    if (!(RECORD_TYPES as readonly string[]).includes(type)) {
      errors.push(`Line ${i + 1}: unsupported type "${typeTok}"`);
      return;
    }
    const value = valueTok.replace(/^"|"$/g, "");
    const rec: RecordInput = { host: normHost(nameTok), type, answer: value };
    if (ttlTok && /^\d+$/.test(ttlTok)) rec.ttl = Math.min(86400, Math.max(60, Number(ttlTok)));
    if (type === "MX" && prioTok && /^\d+$/.test(prioTok)) rec.priority = Number(prioTok);
    records.push(rec);
  });
  return { records, errors };
}

export async function importDnsRecords(domainId: string, text: string): Promise<BulkResult> {
  const { records, errors } = await parseDnsImport(text);
  if (errors.length && records.length === 0) {
    return { error: errors.join("; ").slice(0, 300) };
  }
  const res = await addDnsRecordsBulk(domainId, records);
  if (errors.length) {
    res.note = `${errors.length} line(s) skipped: ${errors.slice(0, 3).join("; ")}${errors.length > 3 ? "…" : ""}`;
  }
  return res;
}

/* ------------------------------------------------------------------ *
 * Reset DNS to a sane default set (strong confirm handled in the UI).
 * Removes all customer-manageable records (A/AAAA/CNAME/TXT/MX/SRV/ALIAS),
 * leaves NS delegation untouched, then re-adds A @ / A www at the platform IP.
 * ------------------------------------------------------------------ */

export async function resetDnsToDefaults(domainId: string): Promise<BulkResult> {
  let ctx;
  try {
    ctx = await ownedActiveDomain(domainId);
  } catch (e) {
    return { error: errMsg(e) };
  }
  const ip = process.env.PUBLIC_IP;
  const removable = new Set(["A", "AAAA", "CNAME", "TXT", "MX", "SRV", "ALIAS"]);
  let removed = 0;
  const failed: { record: string; reason: string }[] = [];
  try {
    const recs = await listRecords(ctx.domain.name);
    for (const r of recs) {
      if (!removable.has(r.type)) continue;
      try {
        await deleteRecord(ctx.domain.name, r.id);
        removed++;
      } catch (e) {
        failed.push({ record: `${r.type} ${r.host || "@"}`, reason: errMsg(e) });
      }
    }
  } catch (e) {
    return { error: `Could not read current records: ${errMsg(e)}` };
  }

  const added: string[] = [];
  if (ip) {
    for (const host of ["", "www"]) {
      try {
        await addRecord(ctx.domain.name, { host, type: "A", answer: ip, ttl: 300 });
        added.push(`A ${host || "@"} → ${ip}`);
      } catch (e) {
        failed.push({ record: `A ${host || "@"}`, reason: errMsg(e) });
      }
    }
  }

  await db.auditLog.create({
    data: { userId: ctx.user.id, action: "domain.dns_reset", detail: `${ctx.domain.name}: removed ${removed}, added ${added.length}` },
  });
  revalidatePath(`/dashboard/domains/${domainId}`);
  return {
    added,
    skipped: [],
    failed: failed.length ? failed : undefined,
    note: `Removed ${removed} record(s)${added.length ? ` and restored a default A record set pointing at ${ip}` : " (no platform IP configured, so no default records were added)"}.`,
  };
}

/* ------------------------------------------------------------------ *
 * URL forwarding / redirects (name.com URL-forwarding API).
 *   GET/POST/DELETE /v4/domains/{domain}/url/forwarding[/{host}]
 * Degrades to a persisted-intent Setting + note when unconfigured.
 * ------------------------------------------------------------------ */

export type Redirect = { host: string; forwardsTo: string; type: string };

const redirectStoreKey = (domainId: string) => `domain-redirect:${domainId}`;

async function readRedirectIntent(domainId: string): Promise<Redirect[]> {
  const s = await db.setting.findUnique({ where: { key: redirectStoreKey(domainId) } });
  if (!s?.value) return [];
  try {
    const parsed = JSON.parse(s.value);
    return Array.isArray(parsed) ? parsed : [];
  } catch {
    return [];
  }
}

async function writeRedirectIntent(domainId: string, list: Redirect[]): Promise<void> {
  await db.setting.upsert({
    where: { key: redirectStoreKey(domainId) },
    create: { key: redirectStoreKey(domainId), value: JSON.stringify(list) },
    update: { value: JSON.stringify(list) },
  });
}

export type RedirectsView = { forwards: Redirect[]; live: boolean; note?: string; error?: string };

/** List forwardings — live from name.com when possible, else persisted intent. */
export async function listRedirects(domainId: string): Promise<RedirectsView> {
  let ctx;
  try {
    ctx = await ownedDomain(domainId);
  } catch (e) {
    return { forwards: [], live: false, error: errMsg(e) };
  }
  if (ctx.domain.status === "ACTIVE" && registrarConfigured()) {
    try {
      const json = await nc("GET", `/v4/domains/${encodeURIComponent(ctx.domain.name)}/url/forwarding`);
      const forwards: Redirect[] = (json.urlForwarding ?? json.urlForwardings ?? []).map((f: any) => ({
        host: f.host ?? "",
        forwardsTo: f.forwardsTo ?? "",
        type: f.type ?? "redirect301",
      }));
      return { forwards, live: true };
    } catch (e) {
      // Fall back to intent store but tell the truth about why.
      const forwards = await readRedirectIntent(domainId);
      return { forwards, live: false, note: `Live forwarding unavailable (${errMsg(e)}); showing saved intent.` };
    }
  }
  const forwards = await readRedirectIntent(domainId);
  return { forwards, live: false, note: "Registrar not connected — showing saved intent that will apply once live." };
}

const REDIRECT_TYPES = ["redirect301", "redirect302", "masked"] as const;

export async function setRedirect(
  domainId: string,
  hostRaw: string,
  forwardsTo: string,
  type: string
): Promise<RedirectsView> {
  let ctx;
  try {
    ctx = await ownedDomain(domainId);
  } catch (e) {
    return { forwards: [], live: false, error: errMsg(e) };
  }
  const host = normHost(hostRaw);
  const t = (REDIRECT_TYPES as readonly string[]).includes(type) ? type : "redirect301";
  const url = z.string().url().max(2000).safeParse(forwardsTo.trim());
  if (!url.success) return { ...(await listRedirects(domainId)), error: "Enter a valid destination URL (including https://)." };

  const canLive = ctx.domain.status === "ACTIVE" && registrarConfigured();
  if (canLive) {
    try {
      // Upsert: delete any existing forwarding for this host, then create.
      try {
        await nc("DELETE", `/v4/domains/${encodeURIComponent(ctx.domain.name)}/url/forwarding/${encodeURIComponent(host)}`);
      } catch {
        /* none existed */
      }
      await nc("POST", `/v4/domains/${encodeURIComponent(ctx.domain.name)}/url/forwarding`, {
        host,
        forwardsTo: url.data,
        type: t,
      });
    } catch (e) {
      return { ...(await listRedirects(domainId)), error: `Registrar rejected the redirect: ${errMsg(e)}` };
    }
  } else {
    const list = (await readRedirectIntent(domainId)).filter((r) => normHost(r.host) !== host);
    list.push({ host, forwardsTo: url.data, type: t });
    await writeRedirectIntent(domainId, list);
  }

  await db.auditLog.create({
    data: { userId: ctx.user.id, action: "domain.redirect_set", detail: `${ctx.domain.name} ${host || "@"} -> ${url.data} (${t})${canLive ? " live" : " intent"}` },
  });
  revalidatePath(`/dashboard/domains/${domainId}`);
  const view = await listRedirects(domainId);
  return {
    ...view,
    note: canLive
      ? "Redirect saved at name.com via URL forwarding. It can take a little while to take effect."
      : "Saved. This redirect will be applied via name.com URL forwarding once the domain is active and the registrar is connected.",
  };
}

export async function deleteRedirect(domainId: string, hostRaw: string): Promise<RedirectsView> {
  let ctx;
  try {
    ctx = await ownedDomain(domainId);
  } catch (e) {
    return { forwards: [], live: false, error: errMsg(e) };
  }
  const host = normHost(hostRaw);
  const canLive = ctx.domain.status === "ACTIVE" && registrarConfigured();
  if (canLive) {
    try {
      await nc("DELETE", `/v4/domains/${encodeURIComponent(ctx.domain.name)}/url/forwarding/${encodeURIComponent(host)}`);
    } catch (e) {
      return { ...(await listRedirects(domainId)), error: `Could not remove redirect: ${errMsg(e)}` };
    }
  }
  const list = (await readRedirectIntent(domainId)).filter((r) => normHost(r.host) !== host);
  await writeRedirectIntent(domainId, list);
  await db.auditLog.create({
    data: { userId: ctx.user.id, action: "domain.redirect_delete", detail: `${ctx.domain.name} ${host || "@"}` },
  });
  revalidatePath(`/dashboard/domains/${domainId}`);
  return { ...(await listRedirects(domainId)), note: "Redirect removed." };
}

/* ------------------------------------------------------------------ *
 * Registrar lock (name.com :lock / :unlock). Persist state + note.
 * ------------------------------------------------------------------ */

const lockStoreKey = (domainId: string) => `domain-lock:${domainId}`;

export type LockView = { locked: boolean; live: boolean; note?: string; error?: string };

export async function getRegistrarLock(domainId: string): Promise<LockView> {
  let ctx;
  try {
    ctx = await ownedDomain(domainId);
  } catch (e) {
    return { locked: false, live: false, error: errMsg(e) };
  }
  if (ctx.domain.status === "ACTIVE" && registrarConfigured()) {
    try {
      const json = await nc("GET", `/v4/domains/${encodeURIComponent(ctx.domain.name)}`);
      const locked = json?.locked === true;
      return { locked, live: true };
    } catch {
      /* fall through to stored intent */
    }
  }
  const s = await db.setting.findUnique({ where: { key: lockStoreKey(domainId) } });
  return { locked: s?.value === "true", live: false };
}

export async function setRegistrarLock(domainId: string, locked: boolean): Promise<LockView> {
  let ctx;
  try {
    ctx = await ownedDomain(domainId);
  } catch (e) {
    return { locked: false, live: false, error: errMsg(e) };
  }
  const canLive = ctx.domain.status === "ACTIVE" && registrarConfigured();
  let live = false;
  let note: string | undefined;
  if (canLive) {
    try {
      await nc("POST", `/v4/domains/${encodeURIComponent(ctx.domain.name)}:${locked ? "lock" : "unlock"}`, {});
      live = true;
      note = locked
        ? "Registrar lock enabled — the domain is protected against unauthorized transfers."
        : "Registrar lock disabled — the domain can now be transferred to another registrar.";
    } catch (e) {
      return { locked: !locked, live: false, error: `Registrar rejected the change: ${errMsg(e)}. Some TLDs manage the lock manually.` };
    }
  } else {
    note = "Saved. This lock preference will be applied at name.com once the domain is active and the registrar is connected.";
  }
  await db.setting.upsert({
    where: { key: lockStoreKey(domainId) },
    create: { key: lockStoreKey(domainId), value: String(locked) },
    update: { value: String(locked) },
  });
  await db.auditLog.create({
    data: { userId: ctx.user.id, action: "domain.registrar_lock", detail: `${ctx.domain.name} -> ${locked ? "locked" : "unlocked"}${live ? " (live)" : ""}` },
  });
  revalidatePath(`/dashboard/domains/${domainId}`);
  return { locked, live, note };
}

import { NextRequest, NextResponse } from "next/server";
import { currentUser } from "@/lib/auth";
import { db } from "@/lib/db";
import { registrarConfigured, listRecords } from "@/lib/registrar";

/**
 * Downloads the domain's current DNS records as a CSV / zone-style text file.
 * The format round-trips through the "Import DNS" paste box:
 *   name,type,value,ttl,priority
 * Comment lines (starting with #) are ignored by the importer.
 *
 * Ownership-checked: the caller must own the domain (or be an admin).
 */
export async function GET(_req: NextRequest, { params }: { params: Promise<{ id: string }> }) {
  const { id } = await params;
  const user = await currentUser();
  if (!user) return NextResponse.json({ error: "unauthorized" }, { status: 401 });

  const domain = await db.domain.findUnique({ where: { id } });
  if (!domain) return NextResponse.json({ error: "not found" }, { status: 404 });
  if (domain.userId !== user.id && user.role !== "ADMIN") {
    return NextResponse.json({ error: "forbidden" }, { status: 403 });
  }

  if (domain.status !== "ACTIVE" || !registrarConfigured()) {
    return NextResponse.json(
      { error: "DNS export is available once the domain is active and the registrar is connected." },
      { status: 409 }
    );
  }

  let records;
  try {
    records = await listRecords(domain.name);
  } catch (e) {
    return NextResponse.json(
      { error: `Could not read DNS records: ${String(e instanceof Error ? e.message : e).slice(0, 200)}` },
      { status: 502 }
    );
  }

  const esc = (v: string) => (/[",\n]/.test(v) ? `"${v.replace(/"/g, '""')}"` : v);
  const lines: string[] = [
    `# DNS export for ${domain.name}`,
    `# Generated ${new Date().toISOString()} by Nxeon`,
    `# Format: name,type,value,ttl,priority   (import via the domain's "Import DNS" box)`,
    `name,type,value,ttl,priority`,
  ];
  for (const r of records) {
    const name = r.host === "" ? "@" : r.host;
    const priority = r.type === "MX" || r.type === "SRV" ? String(r.priority ?? "") : "";
    lines.push([esc(name), r.type, esc(r.answer), String(r.ttl ?? 300), priority].join(","));
  }

  const body = lines.join("\n") + "\n";
  return new NextResponse(body, {
    status: 200,
    headers: {
      "Content-Type": "text/csv; charset=utf-8",
      "Content-Disposition": `attachment; filename="${domain.name}-dns.csv"`,
      "Cache-Control": "private, no-store",
    },
  });
}

"use client";

import { useMemo, useState, useTransition } from "react";
import { addDnsRecordsBulk, type RecordInput, type BulkResult } from "@/lib/actions-domains-dns";
import { Badge } from "@/components/ui/primitives";

export type QuickServer = { id: string; label: string; ip: string };

function RecordPreview({ records }: { records: RecordInput[] }) {
  if (records.length === 0) return null;
  return (
    <div className="mt-3 overflow-x-auto rounded-xl border border-white/[0.06] bg-black/20">
      <table className="w-full min-w-[420px] text-xs">
        <thead>
          <tr className="text-left text-slate-500">
            <th className="px-3 py-2 font-medium">Type</th>
            <th className="px-3 py-2 font-medium">Name</th>
            <th className="px-3 py-2 font-medium">Value</th>
            <th className="px-3 py-2 font-medium">TTL</th>
          </tr>
        </thead>
        <tbody className="font-mono">
          {records.map((r, i) => (
            <tr key={i} className="border-t border-white/[0.05]">
              <td className="px-3 py-1.5 text-brand-300">
                {r.type}
                {r.type === "MX" && r.priority !== undefined ? (
                  <span className="ml-1 text-slate-500">p{r.priority}</span>
                ) : null}
              </td>
              <td className="px-3 py-1.5 text-slate-300">{r.host === "" ? "@" : r.host}</td>
              <td className="max-w-[260px] truncate px-3 py-1.5 text-slate-400" title={r.answer}>
                {r.answer}
              </td>
              <td className="px-3 py-1.5 text-slate-500">{r.ttl ?? 300}</td>
            </tr>
          ))}
        </tbody>
      </table>
    </div>
  );
}

function ResultBox({ result }: { result: BulkResult }) {
  if (result.error) {
    return (
      <div className="mt-3 rounded-xl border border-red-500/30 bg-red-500/10 px-3 py-2 text-sm text-red-300">
        {result.error}
      </div>
    );
  }
  return (
    <div className="mt-3 space-y-1.5 text-xs">
      {result.added && result.added.length > 0 && (
        <p className="text-emerald-400">
          Added {result.added.length}: <span className="text-slate-400">{result.added.join(", ")}</span>
        </p>
      )}
      {result.skipped && result.skipped.length > 0 && (
        <p className="text-slate-500">Already present ({result.skipped.length}): {result.skipped.join(", ")}</p>
      )}
      {result.failed && result.failed.length > 0 && (
        <p className="text-amber-400">
          Failed: {result.failed.map((f) => `${f.record} (${f.reason})`).join("; ")}
        </p>
      )}
      {result.note && <p className="text-slate-500">{result.note}</p>}
      {result.added && result.added.length === 0 && (!result.failed || result.failed.length === 0) && (
        <p className="text-slate-500">Everything was already in place — nothing to add.</p>
      )}
    </div>
  );
}

function Preset({
  domainId,
  title,
  description,
  badge,
  records,
  disabled,
  disabledNote,
  children,
}: {
  domainId: string;
  title: string;
  description: string;
  badge?: string;
  records: RecordInput[];
  disabled?: boolean;
  disabledNote?: string;
  children?: React.ReactNode;
}) {
  const [open, setOpen] = useState(false);
  const [pending, start] = useTransition();
  const [result, setResult] = useState<BulkResult | null>(null);

  function apply() {
    start(async () => {
      setResult(null);
      const res = await addDnsRecordsBulk(domainId, records);
      setResult(res);
    });
  }

  return (
    <div className="rounded-xl border border-white/[0.07] bg-white/[0.02] p-4">
      <button
        type="button"
        className="flex w-full items-start justify-between gap-3 text-left"
        onClick={() => setOpen((o) => !o)}
      >
        <div>
          <div className="flex items-center gap-2">
            <h3 className="text-sm font-semibold">{title}</h3>
            {badge && <Badge tone="brand">{badge}</Badge>}
          </div>
          <p className="mt-1 text-xs text-slate-400">{description}</p>
        </div>
        <span className={`mt-1 text-slate-500 transition-transform ${open ? "rotate-180" : ""}`}>▾</span>
      </button>

      {open && (
        <div className="mt-4">
          {children}
          {disabled ? (
            <p className="mt-3 text-xs text-amber-400">{disabledNote ?? "Not available right now."}</p>
          ) : (
            <>
              <p className="mt-3 text-xs text-slate-500">
                This will add the following record{records.length === 1 ? "" : "s"} (existing ones are skipped):
              </p>
              <RecordPreview records={records} />
              <button
                className="btn-primary mt-3"
                disabled={pending || records.length === 0}
                onClick={() => {
                  if (!window.confirm(`Add ${records.length} DNS record(s) for "${title}"?`)) return;
                  apply();
                }}
              >
                {pending ? "Applying…" : `Apply "${title}"`}
              </button>
            </>
          )}
          {result && <ResultBox result={result} />}
        </div>
      )}
    </div>
  );
}

export function DnsQuickSetup({
  domainId,
  domainName,
  servers,
  publicIp,
}: {
  domainId: string;
  domainName: string;
  servers: QuickServer[];
  publicIp: string;
}) {
  // ---- Point at my server ----
  const targets = useMemo<QuickServer[]>(() => {
    const list = [...servers];
    if (publicIp) list.push({ id: "__platform__", label: `Platform IP (${publicIp})`, ip: publicIp });
    return list;
  }, [servers, publicIp]);

  const [targetId, setTargetId] = useState<string>(targets[0]?.id ?? "");
  const [wwwMode, setWwwMode] = useState<"a" | "cname">("a");
  const target = targets.find((t) => t.id === targetId);

  const pointRecords = useMemo<RecordInput[]>(() => {
    if (!target?.ip) return [];
    const recs: RecordInput[] = [{ host: "", type: "A", answer: target.ip, ttl: 300 }];
    if (wwwMode === "a") recs.push({ host: "www", type: "A", answer: target.ip, ttl: 300 });
    else recs.push({ host: "www", type: "CNAME", answer: `${domainName}.`, ttl: 300 });
    return recs;
  }, [target, wwwMode, domainName]);

  // ---- Google Workspace ----
  const googleWorkspace: RecordInput[] = [
    { host: "", type: "MX", answer: "aspmx.l.google.com.", ttl: 3600, priority: 1 },
    { host: "", type: "MX", answer: "alt1.aspmx.l.google.com.", ttl: 3600, priority: 5 },
    { host: "", type: "MX", answer: "alt2.aspmx.l.google.com.", ttl: 3600, priority: 5 },
    { host: "", type: "MX", answer: "alt3.aspmx.l.google.com.", ttl: 3600, priority: 10 },
    { host: "", type: "MX", answer: "alt4.aspmx.l.google.com.", ttl: 3600, priority: 10 },
    { host: "", type: "TXT", answer: "v=spf1 include:_spf.google.com ~all", ttl: 3600 },
  ];

  // ---- Email deliverability ----
  const [dmarcPolicy, setDmarcPolicy] = useState<"none" | "quarantine" | "reject">("none");
  const [dmarcRua, setDmarcRua] = useState<string>("");
  const dmarcValue = useMemo(() => {
    const rua = dmarcRua.trim() ? `; rua=mailto:${dmarcRua.trim()}` : "";
    return `v=DMARC1; p=${dmarcPolicy}${rua}`;
  }, [dmarcPolicy, dmarcRua]);
  const emailRecords: RecordInput[] = [
    { host: "", type: "TXT", answer: "v=spf1 ~all", ttl: 3600 },
    { host: "_dmarc", type: "TXT", answer: dmarcValue, ttl: 3600 },
  ];

  // ---- Google site verification ----
  const [gToken, setGToken] = useState<string>("");
  const gTokenClean = gToken.trim().replace(/^google-site-verification=/i, "");
  const verifyRecords: RecordInput[] = gTokenClean
    ? [{ host: "", type: "TXT", answer: `google-site-verification=${gTokenClean}`, ttl: 3600 }]
    : [];

  return (
    <div className="card">
      <div className="mb-1 flex items-center justify-between">
        <h2 className="font-semibold">Quick setup</h2>
        <Badge tone="brand">one-click DNS</Badge>
      </div>
      <p className="mb-4 text-sm text-slate-400">
        Add the right records for common setups in one click. Each preset shows exactly what it adds and
        skips anything already present.
      </p>

      <div className="space-y-3">
        <Preset
          domainId={domainId}
          title="Point this domain at my server"
          badge="VPS"
          description="Set @ and www to one of your servers (or the platform IP) so your site loads on this domain."
          records={pointRecords}
          disabled={targets.length === 0}
          disabledNote="You don't have any servers yet — deploy a server first, then point your domain at it."
        >
          <div className="grid gap-3 sm:grid-cols-2">
            <div>
              <label className="label">Target</label>
              <select className="input" value={targetId} onChange={(e) => setTargetId(e.target.value)}>
                {targets.map((t) => (
                  <option key={t.id} value={t.id}>
                    {t.label}
                    {t.ip ? ` — ${t.ip}` : " (no IP yet)"}
                  </option>
                ))}
              </select>
            </div>
            <div>
              <label className="label">www record</label>
              <select className="input" value={wwwMode} onChange={(e) => setWwwMode(e.target.value as "a" | "cname")}>
                <option value="a">A record (same IP)</option>
                <option value="cname">CNAME → {domainName}</option>
              </select>
            </div>
          </div>
          {target && !target.ip && (
            <p className="mt-2 text-xs text-amber-400">
              This server has no IP address yet — pick another target or wait for provisioning to finish.
            </p>
          )}
        </Preset>

        <Preset
          domainId={domainId}
          title="Google Workspace / Gmail"
          badge="Email"
          description="Add Google's MX records plus an SPF record so email for this domain flows through Gmail."
          records={googleWorkspace}
        />

        <Preset
          domainId={domainId}
          title="Email deliverability (SPF + DMARC)"
          badge="Email"
          description="Add a baseline SPF record and a DMARC policy so your mail is trusted and not spoofed."
          records={emailRecords}
        >
          <div className="grid gap-3 sm:grid-cols-2">
            <div>
              <label className="label">DMARC policy</label>
              <select className="input" value={dmarcPolicy} onChange={(e) => setDmarcPolicy(e.target.value as any)}>
                <option value="none">none (monitor only)</option>
                <option value="quarantine">quarantine (spam folder)</option>
                <option value="reject">reject (block)</option>
              </select>
            </div>
            <div>
              <label className="label">Reports to (optional)</label>
              <input
                className="input"
                placeholder="you@example.com"
                value={dmarcRua}
                onChange={(e) => setDmarcRua(e.target.value)}
                autoComplete="off"
                spellCheck={false}
              />
            </div>
          </div>
          <p className="mt-2 text-xs text-slate-500">
            DKIM must be generated by your mail provider — once you have the DKIM key, add it as a TXT
            record (usually at <span className="font-mono text-slate-400">selector._domainkey</span>) using the
            DNS manager below.
          </p>
        </Preset>

        <Preset
          domainId={domainId}
          title="Google site verification"
          badge="Verify"
          description="Paste the verification token from Google Search Console to prove you own this domain."
          records={verifyRecords}
          disabled={!gTokenClean}
          disabledNote="Paste your verification token to preview the TXT record."
        >
          <div>
            <label className="label">Verification token</label>
            <input
              className="input font-mono text-xs"
              placeholder="google-site-verification=xxxxxxxxxxxxxxxx"
              value={gToken}
              onChange={(e) => setGToken(e.target.value)}
              autoComplete="off"
              spellCheck={false}
            />
          </div>
        </Preset>
      </div>
    </div>
  );
}

"use client";

import { useState, useTransition } from "react";
import {
  setRedirect,
  deleteRedirect,
  type Redirect,
  type RedirectsView,
} from "@/lib/actions-domains-dns";
import { Badge } from "@/components/ui/primitives";

const TYPE_LABEL: Record<string, string> = {
  redirect301: "Permanent (301)",
  redirect302: "Temporary (302)",
  masked: "Masked (framed)",
};

export function DomainRedirects({
  domainId,
  domainName,
  initial,
}: {
  domainId: string;
  domainName: string;
  initial: RedirectsView;
}) {
  const [view, setView] = useState<RedirectsView>(initial);
  const [host, setHost] = useState<"" | "www">("");
  const [target, setTarget] = useState("");
  const [type, setType] = useState("redirect301");
  const [error, setError] = useState<string | null>(null);
  const [note, setNote] = useState<string | null>(initial.note ?? null);
  const [pending, start] = useTransition();

  function submit() {
    start(async () => {
      setError(null);
      setNote(null);
      const res = await setRedirect(domainId, host, target, type);
      if (res.error) setError(res.error);
      else {
        setView(res);
        setNote(res.note ?? "Saved.");
        setTarget("");
      }
    });
  }

  function remove(h: string) {
    start(async () => {
      setError(null);
      setNote(null);
      const res = await deleteRedirect(domainId, h);
      if (res.error) setError(res.error);
      else {
        setView(res);
        setNote(res.note ?? "Removed.");
      }
    });
  }

  return (
    <div className="card">
      <div className="mb-1 flex items-center justify-between">
        <h2 className="font-semibold">URL redirects</h2>
        {view.live ? <Badge tone="green">live via name.com</Badge> : <Badge tone="slate">saved intent</Badge>}
      </div>
      <p className="mb-4 text-sm text-slate-400">
        Forward this domain (or the <span className="font-mono text-brand-300">www</span> host) to another URL —
        handy for sending a brand domain to your main site. Implemented with name.com URL forwarding; a 301
        redirect is best for SEO, masked keeps your domain in the address bar.
      </p>

      {view.forwards.length > 0 && (
        <div className="mb-4 space-y-2">
          {view.forwards.map((f: Redirect, i) => (
            <div
              key={`${f.host}-${i}`}
              className="flex flex-wrap items-center justify-between gap-2 rounded-xl border border-white/[0.06] bg-white/[0.02] px-3 py-2"
            >
              <div className="min-w-0 text-sm">
                <span className="font-mono text-brand-300">
                  {f.host === "" ? domainName : `${f.host}.${domainName}`}
                </span>
                <span className="mx-2 text-slate-500">→</span>
                <span className="break-all font-mono text-xs text-slate-300">{f.forwardsTo}</span>
              </div>
              <div className="flex items-center gap-2">
                <Badge tone="slate">{TYPE_LABEL[f.type] ?? f.type}</Badge>
                <button
                  className="btn-danger px-2.5 py-1 text-xs"
                  disabled={pending}
                  onClick={() => {
                    if (!window.confirm(`Remove the redirect for ${f.host === "" ? domainName : f.host}?`)) return;
                    remove(f.host);
                  }}
                >
                  Remove
                </button>
              </div>
            </div>
          ))}
        </div>
      )}

      <div className="grid gap-3 sm:grid-cols-2 lg:grid-cols-4">
        <div>
          <label className="label">Source</label>
          <select className="input" value={host} onChange={(e) => setHost(e.target.value as "" | "www")}>
            <option value="">{domainName} (root)</option>
            <option value="www">www.{domainName}</option>
          </select>
        </div>
        <div className="lg:col-span-2">
          <label className="label">Destination URL</label>
          <input
            className="input font-mono text-xs"
            placeholder="https://example.com/landing"
            value={target}
            onChange={(e) => setTarget(e.target.value)}
            autoComplete="off"
            spellCheck={false}
          />
        </div>
        <div>
          <label className="label">Type</label>
          <select className="input" value={type} onChange={(e) => setType(e.target.value)}>
            <option value="redirect301">Permanent (301)</option>
            <option value="redirect302">Temporary (302)</option>
            <option value="masked">Masked (framed)</option>
          </select>
        </div>
      </div>

      <div className="mt-3 flex items-center justify-end">
        <button className="btn-primary" disabled={pending || !target.trim()} onClick={submit}>
          {pending ? "Saving…" : "Save redirect"}
        </button>
      </div>

      {note && <p className="mt-3 text-sm text-emerald-400">{note}</p>}
      {error && <p className="mt-3 text-sm text-red-400">{error}</p>}
      {!view.live && (
        <p className="mt-3 text-xs text-slate-500">
          Redirects apply through name.com URL forwarding once the domain is active and the registrar is
          connected. Note: URL forwarding replaces any A/CNAME record on the forwarded host.
        </p>
      )}
    </div>
  );
}

import { Badge } from "@/components/ui/primitives";

export type ChecklistItem = { label: string; done: boolean; hint?: string };

/**
 * Small progress card summarising how "set up" a domain is. Pure presentational —
 * the parent page computes the items from the domain, its DNS records, and the
 * user's servers, so there is no client-side logic here.
 */
export function DomainChecklist({ items }: { items: ChecklistItem[] }) {
  const done = items.filter((i) => i.done).length;
  const pct = items.length ? Math.round((done / items.length) * 100) : 0;
  const complete = done === items.length;

  return (
    <div className="card">
      <div className="mb-3 flex items-center justify-between">
        <h2 className="font-semibold">Setup checklist</h2>
        <Badge tone={complete ? "green" : done === 0 ? "slate" : "brand"}>
          {done}/{items.length} done
        </Badge>
      </div>

      <div className="mb-4 h-2 overflow-hidden rounded-full bg-white/[0.06]">
        <div
          className="h-full rounded-full bg-gradient-to-r from-accent-blue to-brand-500 transition-all"
          style={{ width: `${pct}%` }}
        />
      </div>

      <ul className="space-y-2.5">
        {items.map((item) => (
          <li key={item.label} className="flex items-start gap-3">
            <span
              className={`mt-0.5 flex h-5 w-5 shrink-0 items-center justify-center rounded-full border text-[11px] ${
                item.done
                  ? "border-emerald-500/50 bg-emerald-500/15 text-emerald-300"
                  : "border-white/10 bg-white/[0.03] text-slate-500"
              }`}
            >
              {item.done ? "✓" : ""}
            </span>
            <div className="min-w-0">
              <p className={`text-sm ${item.done ? "text-slate-200" : "text-slate-400"}`}>{item.label}</p>
              {!item.done && item.hint && <p className="text-xs text-slate-500">{item.hint}</p>}
            </div>
          </li>
        ))}
      </ul>

      {complete && (
        <p className="mt-4 text-sm text-emerald-400">Nice — this domain is fully configured.</p>
      )}
    </div>
  );
}

