/* -------------------------------------------------------------------------- *
 * Import / Export / Reset — extra DNS tools mounted alongside quick setup.
 * -------------------------------------------------------------------------- */

export function DnsImportExportReset({
  domainId,
  publicIp,
}: {
  domainId: string;
  publicIp: string;
}) {
  const [text, setText] = useState("");
  const [importResult, setImportResult] = useState<BulkResult | null>(null);
  const [resetResult, setResetResult] = useState<BulkResult | null>(null);
  const [importing, startImport] = useTransition();
  const [resetting, startReset] = useTransition();

  function runImport() {
    startImport(async () => {
      setImportResult(null);
      const res = await importDnsRecords(domainId, text);
      setImportResult(res);
      if (!res.error) setText("");
    });
  }

  function runReset() {
    const phrase = window.prompt(
      "This removes ALL A/AAAA/CNAME/TXT/MX/SRV records and restores a default set" +
        (publicIp ? ` pointing at ${publicIp}` : "") +
        ".\n\nType RESET to confirm."
    );
    if (phrase !== "RESET") return;
    startReset(async () => {
      setResetResult(null);
      const res = await resetDnsToDefaults(domainId);
      setResetResult(res);
    });
  }

  return (
    <div className="card">
      <div className="mb-1 flex items-center justify-between">
        <h2 className="font-semibold">Import / export &amp; reset</h2>
        <Badge tone="slate">bulk tools</Badge>
