/* -------------------------------------------------------------------------- *
 * Registrar lock — protects the domain against unauthorized transfers.
 * -------------------------------------------------------------------------- */

export function RegistrarLockCard({
  domainId,
  initial,
}: {
  domainId: string;
  initial: LockView;
}) {
  const [locked, setLocked] = useState(initial.locked);
  const [live, setLive] = useState(initial.live);
  const [note, setNote] = useState<string | null>(null);
  const [error, setError] = useState<string | null>(null);
  const [pending, start] = useTransition();

  function toggle() {
    const next = !locked;
    setLocked(next); // optimistic
    start(async () => {
      setError(null);
      setNote(null);
      const res = await setRegistrarLock(domainId, next);
      if (res.error) {
        setLocked(!next);
        setError(res.error);
      } else {
        setLocked(res.locked);
        setLive(res.live);
        setNote(res.note ?? "Saved.");
      }
    });
  }

  return (
    <div className="card">
      <div className="mb-1 flex items-center justify-between">
        <h2 className="font-semibold">Registrar lock</h2>
        <button
          type="button"
          disabled={pending}
          onClick={toggle}
          title={locked ? "Locked — click to unlock" : "Unlocked — click to lock"}
          className={`relative h-5 w-9 cursor-pointer rounded-full transition-colors disabled:opacity-50 ${
            locked ? "bg-gradient-to-r from-accent-blue to-brand-500" : "bg-white/10"
          }`}
        >
          <span
            className={`absolute top-0.5 h-4 w-4 rounded-full bg-white transition-all ${
              locked ? "left-[18px]" : "left-0.5"
            }`}
          />
        </button>
      </div>
      <p className="text-sm text-slate-400">
        When locked, the domain can&apos;t be transferred to another registrar without first unlocking it —
        a strong defence against domain hijacking. Unlock only when you&apos;re starting a transfer out.
      </p>
      <p className="mt-2 text-xs text-slate-500">
        Currently <span className="font-medium text-slate-300">{locked ? "locked" : "unlocked"}</span>
        {live ? " (live at name.com)" : " (saved — applies once the registrar is connected)"}.
      </p>
      {note && <p className="mt-3 text-sm text-emerald-400">{note}</p>}
      {error && <p className="mt-3 text-sm text-red-400">{error}</p>}
    </div>
  );
}
